    // 20ms\u3054\u3068\u306B\u30A2\u30CA\u30ED\u30B0\u5024\u3092\u8AAD\u307F\u53D6\u308B\n    if (orpArrayIndex==ArrayLenth) {\n      orpArrayIndex=0;\n    }   \n    orpValue=((30*(double)VOLTAGE*1000)-(75*avergearray(orpArray, ArrayLenth)*VOLTAGE*1000/1024))/75-offset;\n  }\n  if(millis() >= printTime)   // 800\u30DF\u30EA\u79D2\u3054\u3068\u306B\u6570\u5024\u3092\u51FA\u529B\n  {\n    if(!is_calibrated) {\n      if(wait_count==0){\n        offset += (int)orpValue; \n        is_calibrated = true;\n        digitalWrite(calPin, LOW);\n        Serial.print("offset: ");\n        Serial.print((int)offset);\n        Serial.println(" mV");\n      }\n      wait_count--;\n    }\n    else {\n      Serial.print("ORP: ");\n      Serial.print((int)orpValue);\n      Serial.println(" mV");\n      digitalWrite(LED,1-digitalRead(LED)); // LED\u30A4\u30F3\u30B8\u30B1\u30FC\u30BF\u306E\u72B6\u614B\u3092\u5909\u63DB      \n    } \n    printTime=millis()+800;   \n  }\n}\n\ndouble avergearray(int* arr, int number){\n  int i;\n  int max,min;\n  double avg;\n  long amount=0;\n  if(number<=0){\n    printf("\u5E73\u5747\u5316\u3059\u308B\u914D\u5217\u306E\u6570\u304C\u4E0D\u6B63\u3067\u3059\uFF01/n");\n    return 0;\n  }\n  if(number<5){   // 5\u672A\u6E80\u306E\u5834\u5408\u3001\u76F4\u63A5\u7D71\u8A08\u3092\u8A08\u7B97\n    for(i=0;i<number;i++){\n      amount+=arr[i];\n    }\n    avg = amount/number;\n    return avg;\n  }else{\n    if(arr[0]<arr[1]){\n      min = arr[0];max=arr[1];\n    }\n    else{\n      min=arr[1];max=arr[0];\n    }\n    for(i=2;i<number;i++){\n      if(arr[i]<min){\n        amount+=min;        // arr<min\n        min=arr[i];\n      }else {\n        if(arr[i]>max){\n          amount+=max;    // arr>max\n          max=arr[i];\n        }else{\n          amount+=arr[i]; // min<=arr<=max\n        }\n      }//if\n    }//for\n    avg = (double)amount/(number-2);\n  }//if\n  return avg;\n}\n'})}),"\n",(0,s.jsx)(n.p,{children:"\u30D7\u30ED\u30B0\u30E9\u30E0\u3092\u4F7F\u7528